mapper.update:
UPDATE CMF_WEIXIN_USERINFO
   SET NICKNAME = #{dto.nickname},SEX = #{dto.sex},LANGUAGE = #{dto.language} ,
       CITY = #{dto.city},PROVINCE = #{dto.province},COUNTRY = #{dto.country},
       HEADIMGURL = #{dto.headimgurl},SUBCRIBE_TIME =SYSDATE
        ,UPDATETIME = SYSDATE,STATUS=#{dto.status}
 WHERE OPENID = #{dto.openid}

UPDATE CMF_WEIXIN_USERINFO
   SET UPDATETIME = SYSDATE,STATUS=#{status}
 WHERE OPENID = #{openid}

UPDATE CMF_WEIXIN_USERINFO
   SET CODE = #{md5Code}
 WHERE OPENID = #{openId}

mapper.select:
	select  count(0)
     FROM cmf_weixin_userinfo
	 WHERE OPENID != #{openId} and CODE = #{md5Code}

SELECT OPENID as openId, USERID as userId, NICKNAME as nickName, SEX as sex, LANGUAGE as language, COUNTRY as country, PROVINCE as province, CITY as city, HEADIMGURL as headImgurl, TO_CHAR(SUBCRIBE_TIME, 'YYYY-MM-DD HH24:MI:SS') AS subscribeTime, TO_CHAR(INSERTTIME, 'YYYY-MM-DD HH24:MI:SS') AS insertTime, TO_CHAR(UPDATETIME, 'YYYY-MM-DD HH24:MI:SS') AS updateTime FROM CMF_WEIXIN_USERINFO T WHERE 1 = 1
AND T.STATUS = #{status}
AND T.STATUS = '1'

SELECT T.CUSTSER_ID
FROM CMWA_WX_USER_INFO T
WHERE T.OPENID = #{openid,jdbcType=VARCHAR}
